# RigorFoundry — npm lockfile classification witnesses
"""Witness npm lockfile classification on lockfiles generated by pinned npm releases.

The clean fixtures were generated by npm 6.14.18, 8.19.4 and 10.9.2 (``lockfileVersion`` 1,
2 and 3; see each ``GENERATED_BY.txt``). Every failing case below is one recorded edit of a
clean fixture, written out in the test that uses it.
"""

from __future__ import annotations

import base64
import hashlib
import json
from collections.abc import Callable
from pathlib import Path
from typing import Any

import pytest
from lockfile_repository_support import fixture_text

from rigor_foundry.lockfile_model import LockedEntry, LockfileRefusal
from rigor_foundry.lockfile_npm import classify_npm_lockfile
from rigor_foundry.lockfile_npmrc import (
    DEFAULT_NPM_REGISTRY,
    UNKNOWN_NPM_REGISTRY,
    NpmRegistryDeclaration,
    read_npmrc,
)

FIXTURES = Path(__file__).resolve().parent / "fixtures" / "lockfiles"
V1 = FIXTURES / "npm-6.14.18-v1" / "package-lock.json.gz"
V2 = FIXTURES / "npm-8.19.4-v2" / "package-lock.json.gz"
V3 = FIXTURES / "npm-10.9.2-v3" / "package-lock.json.gz"
SHA1 = "sha1-" + base64.b64encode(hashlib.sha1(b"x", usedforsecurity=False).digest()).decode()
SHA512 = "sha512-" + base64.b64encode(hashlib.sha512(b"x").digest()).decode()
COMMIT = "98e8ff1da1a89f93d1397a24d7413ed15421c139"
BUNDLED = 50  # inBundle (v2, v3) or bundled (v1) entries npm wrote in each fixture
Document = dict[str, Any]


def _entries(
    text: str, registry: NpmRegistryDeclaration = DEFAULT_NPM_REGISTRY, lock_dir: str = ""
) -> dict[str, LockedEntry]:
    """Classify a lockfile and index its entries by key."""
    _, entries = classify_npm_lockfile(text, lock_dir, registry)
    return {entry.key: entry for entry in entries}


def _edited(path: Path, edit: Callable[[Document], None]) -> str:
    """Return a clean fixture after one recorded edit, written as npm writes it."""
    document = json.loads(fixture_text(path))
    edit(document)
    return json.dumps(document, indent=2) + "\n"


def _v3_package(key: str, **fields: Any) -> Callable[[Document], None]:
    """Return an edit that replaces one version 3 package entry's fields."""

    def edit(document: Document) -> None:
        """Replace the entry."""
        document["packages"][key] = fields

    return edit


@pytest.mark.parametrize(("path", "version"), [(V1, "1"), (V2, "2"), (V3, "3")])
def test_each_clean_fixture_classifies_every_entry_without_findings(
    path: Path, version: str
) -> None:
    """The real npm output of every supported version pins every entry and finds nothing.

    Parameters
    ----------
    path : Path
        The clean fixture.
    version : str
        Its ``lockfileVersion``.
    """
    text = fixture_text(path)
    format_version, ordered = classify_npm_lockfile(text, "", DEFAULT_NPM_REGISTRY)
    assert format_version == version
    entries = {entry.key: entry for entry in ordered}
    assert all(not entry.findings for entry in ordered)
    assert [(entry.line, entry.key) for entry in ordered] == sorted(
        (entry.line, entry.key) for entry in ordered
    )
    for name in ("debug", "ms", "bundle-dependencies"):
        entry = entries[f"node_modules/{name}"]
        assert entry.entry_class == "artifact-pinned"
        assert entry.digest_algorithms == ("sha512",)
        assert entry.digest_scope == "artifact"
        assert entry.origin == "registry.npmjs.org"
    git = entries["node_modules/is-number"]
    assert git.entry_class == "commit-pinned"
    assert git.commit_hash_algorithm == "sha1"
    assert git.origin == "github.com"
    assert git.digest_algorithms == (() if version == "1" else ("sha512",))
    assert entries["node_modules/local-lib"].entry_class == "local"
    bundled = [entry for entry in ordered if entry.inherited_from is not None]
    assert len(bundled) == BUNDLED
    assert {entry.inherited_from for entry in bundled} == {"node_modules/bundle-dependencies"}
    assert {(entry.entry_class, entry.digest_scope) for entry in bundled} == {
        ("artifact-pinned", "parent-artifact")
    }
    if version != "1":
        assert entries["local-lib"].entry_class == "local"


def test_an_entry_points_at_the_line_where_its_key_is_written() -> None:
    """The line is the line of the entry's key in the tracked file, in every version."""
    for path in (V1, V2, V3):
        text = fixture_text(path)
        entry = _entries(text)["node_modules/debug"]
        written = text.splitlines()[entry.line - 1]
        assert '"debug": {' in written or '"node_modules/debug": {' in written


@pytest.mark.parametrize(
    ("integrity", "entry_class", "findings", "algorithms"),
    [
        (None, "unpinned", ("missing-digest",), ()),
        (SHA1, "unpinned", ("weak-digest",), ("sha1",)),
        (f"{SHA1} {SHA512}", "artifact-pinned", (), ("sha1", "sha512")),
        (f"{SHA512} sha512-!!!", "unpinned", ("malformed-digest",), ("sha512",)),
        ("", "unpinned", ("malformed-digest",), ()),
        (7, "unpinned", ("malformed-digest",), ()),
    ],
)
def test_a_registry_artifact_is_pinned_only_by_a_strong_well_formed_digest(
    integrity: object, entry_class: str, findings: tuple[str, ...], algorithms: tuple[str, ...]
) -> None:
    """Missing, weak-only and malformed digests leave the artifact unpinned and named.

    Parameters
    ----------
    integrity : object
        The edited ``integrity`` of ``node_modules/ms``; ``None`` removes the field.
    entry_class : str
        The expected class.
    findings : tuple[str, ...]
        The expected findings.
    algorithms : tuple[str, ...]
        The algorithms that decode.
    """
    fields: dict[str, Any] = {
        "version": "2.1.2",
        "resolved": "https://registry.npmjs.org/ms/-/ms-2.1.2.tgz",
    }
    if integrity is not None:
        fields["integrity"] = integrity
    entry = _entries(_edited(V3, _v3_package("node_modules/ms", **fields)))["node_modules/ms"]
    assert entry.entry_class == entry_class
    assert entry.findings == findings
    assert entry.digest_algorithms == algorithms
    assert entry.form == (None if entry_class == "artifact-pinned" else "artifact")


@pytest.mark.parametrize(
    ("resolved", "entry_class", "findings", "algorithm", "origin"),
    [
        (f"git+ssh://git@github.com/a/b.git#{COMMIT}", "commit-pinned", (), "sha1", "github.com"),
        (
            f"git+https://gitlab.example/a/b.git#{'c' * 64}",
            "commit-pinned",
            (),
            "sha256",
            "gitlab.example",
        ),
        (f"git://example.org/a/b.git#{COMMIT}", "commit-pinned", (), "sha1", "example.org"),
        (f"git+file:///srv/repo.git#{COMMIT}", "commit-pinned", (), "sha1", None),
        (f"gitlab:a/b#{COMMIT}", "commit-pinned", (), "sha1", "gitlab.com"),
        (f"bitbucket:a/b#{COMMIT}", "commit-pinned", (), "sha1", "bitbucket.org"),
        (f"gist:abc#{COMMIT}", "commit-pinned", (), "sha1", "gist.github.com"),
        (
            "git+ssh://git@github.com/a/b.git#main",
            "unpinned",
            ("floating-ref",),
            None,
            "github.com",
        ),
        (f"github:a/b#{COMMIT[:7]}", "unpinned", ("floating-ref",), None, "github.com"),
        ("github:a/b#semver:^1.0.0", "unpinned", ("floating-ref",), None, "github.com"),
        ("git+https://github.com/a/b.git", "unpinned", ("floating-ref",), None, "github.com"),
        (f"github:a/b#{COMMIT.upper()}", "unpinned", ("floating-ref",), None, "github.com"),
    ],
)
def test_a_vcs_source_is_pinned_only_by_a_full_commit(
    resolved: str,
    entry_class: str,
    findings: tuple[str, ...],
    algorithm: str | None,
    origin: str | None,
) -> None:
    """A full lower-case 40- or 64-hex commit pins a VCS source; anything else floats.

    Parameters
    ----------
    resolved : str
        The edited ``resolved`` of ``node_modules/is-number``, without ``integrity``.
    entry_class : str
        The expected class.
    findings : tuple[str, ...]
        The expected findings.
    algorithm : str | None
        The expected commit hash algorithm.
    origin : str | None
        The recorded host.
    """
    edit = _v3_package("node_modules/is-number", version="7.0.0", resolved=resolved)
    entry = _entries(_edited(V3, edit))["node_modules/is-number"]
    assert entry.entry_class == entry_class
    assert entry.findings == findings
    assert entry.commit_hash_algorithm == algorithm
    assert entry.origin == origin
    assert entry.digest_scope is None


def test_a_malformed_digest_unpins_even_a_full_commit() -> None:
    """A git entry with a malformed ``integrity`` is unpinned and names it."""
    edit = _v3_package(
        "node_modules/is-number",
        version="7.0.0",
        resolved=f"github:a/b#{COMMIT}",
        integrity=f"{SHA512} sha512-!!!",
    )
    entry = _entries(_edited(V3, edit))["node_modules/is-number"]
    assert (entry.entry_class, entry.form, entry.findings) == (
        "unpinned",
        "vcs",
        ("malformed-digest",),
    )
    assert entry.digest_scope == "artifact"


def test_the_registry_placeholder_scope_and_other_hosts_are_compared() -> None:
    """Literal hosts mismatch; the placeholder matches; an unknown declaration is unknown."""

    def edit(document: Document) -> None:
        """Move ``ms`` to another host and add a scoped package."""
        packages = document["packages"]
        packages["node_modules/ms"]["resolved"] = "https://evil.example/ms/-/ms-2.1.2.tgz"
        packages["node_modules/@acme/tool"] = {
            "version": "1.0.0",
            "resolved": "https://acme.example/@acme/tool/-/tool-1.0.0.tgz",
            "integrity": SHA512,
        }

    text = _edited(V3, edit)
    default = _entries(text)
    assert default["node_modules/ms"].findings == ("origin-mismatch",)
    assert default["node_modules/ms"].entry_class == "artifact-pinned"
    assert default["node_modules/@acme/tool"].findings == ("origin-mismatch",)
    scoped = _entries(text, read_npmrc("@acme:registry=https://acme.example/\n"))
    assert scoped["node_modules/@acme/tool"].findings == ()
    assert scoped["node_modules/debug"].findings == ()
    unknown = _entries(text, UNKNOWN_NPM_REGISTRY)
    assert unknown["node_modules/debug"].findings == ("origin-unknown",)
    assert unknown["node_modules/debug"].entry_class == "artifact-pinned"


@pytest.mark.parametrize(
    ("registry", "origin", "findings"),
    [
        (DEFAULT_NPM_REGISTRY, "registry.npmjs.org", ()),
        (read_npmrc("registry=https://npm.internal.example/\n"), "npm.internal.example", ()),
        (read_npmrc("@acme:registry=https://acme.example/\n"), "acme.example", ()),
        (UNKNOWN_NPM_REGISTRY, None, ("origin-unknown",)),
    ],
)
def test_an_exact_version_without_a_url_comes_from_the_declared_registry(
    registry: NpmRegistryDeclaration, origin: str | None, findings: tuple[str, ...]
) -> None:
    """With ``resolved`` omitted, the artifact's origin is the registry declared for it.

    Parameters
    ----------
    registry : NpmRegistryDeclaration
        The declaration.
    origin : str | None
        The recorded origin.
    findings : tuple[str, ...]
        The expected findings.
    """
    edit = _v3_package("node_modules/@acme/tool", version="1.0.0", integrity=SHA512)
    entry = _entries(_edited(V3, edit), registry)["node_modules/@acme/tool"]
    assert entry.entry_class == "artifact-pinned"
    assert entry.origin == origin
    assert entry.findings == findings


@pytest.mark.parametrize(
    ("lock_dir", "fields", "entry_class"),
    [
        ("", {"resolved": "local-lib", "link": True}, "local"),
        ("web", {"resolved": "../shared", "link": True}, "local"),
        ("", {"resolved": "../outside", "link": True}, "unpinned"),
        ("web", {"resolved": "../../outside", "link": True}, "unpinned"),
        ("", {"resolved": "/srv/outside", "link": True}, "unpinned"),
        ("", {"resolved": "C:/outside", "link": True}, "unpinned"),
        ("", {"resolved": "..\\outside", "link": True}, "unpinned"),
        ("", {"version": "file:vendor/x.tgz", "resolved": "file:vendor/x.tgz"}, "local"),
        ("", {"version": "1.0.0", "resolved": "file:../x.tgz"}, "unpinned"),
    ],
)
def test_a_local_source_is_pinned_only_inside_the_repository(
    lock_dir: str, fields: dict[str, Any], entry_class: str
) -> None:
    """A path that leaves the repository root, by any spelling, is an unpinned path.

    Parameters
    ----------
    lock_dir : str
        The directory holding the lockfile.
    fields : dict[str, Any]
        The edited ``node_modules/local-lib`` entry.
    entry_class : str
        The expected class.
    """
    entry = _entries(
        _edited(V3, _v3_package("node_modules/local-lib", **fields)), lock_dir=lock_dir
    )
    local = entry["node_modules/local-lib"]
    assert local.entry_class == entry_class
    if entry_class == "unpinned":
        assert (local.form, local.findings) == ("path", ("path-escape",))


def test_a_link_target_outside_the_repository_is_a_path_escape() -> None:
    """A ``packages`` key that is a path, not an installed package, is checked as a path."""

    def edit(document: Document) -> None:
        """Point the link target outside the repository."""
        packages = document["packages"]
        packages["../outside"] = packages.pop("local-lib")

    entries = _entries(_edited(V3, edit))
    assert entries["../outside"].findings == ("path-escape",)


def test_an_installed_package_under_a_link_target_is_not_a_local_path() -> None:
    """``local-lib/node_modules/x`` is a registry package installed for the linked package."""
    edit = _v3_package(
        "local-lib/node_modules/x",
        version="1.0.0",
        resolved="https://registry.npmjs.org/x/-/x-1.0.0.tgz",
        integrity=SHA512,
    )
    entry = _entries(_edited(V3, edit))["local-lib/node_modules/x"]
    assert (entry.entry_class, entry.origin) == ("artifact-pinned", "registry.npmjs.org")


@pytest.mark.parametrize(
    "fields",
    [
        {"version": "1.0.0", "resolved": "ftp://mirror.example/x.tgz", "integrity": SHA512},
        {"version": "1.0.0", "resolved": 7},
        {"link": True},
        {"resolved": "https://registry.npmjs.org/x/-/x-1.0.0.tgz", "integrity": SHA512},
        {"version": "latest"},
        {"version": "", "resolved": "https://registry.npmjs.org/x/-/x-1.0.0.tgz"},
        {"inBundle": True, "version": "1.0.0"},
    ],
)
def test_a_form_the_rules_do_not_know_is_unclassified(fields: dict[str, Any]) -> None:
    """Each form the rules do not know is ``unclassified`` with ``unknown-form``.

    The forms are an unknown scheme, a wrong type, a link with no target, a missing or
    inexact version, and a bundled entry with no ancestor.

    Parameters
    ----------
    fields : dict[str, Any]
        The edited ``node_modules/x`` entry.
    """
    entry = _entries(_edited(V3, _v3_package("node_modules/x", **fields)))["node_modules/x"]
    assert (entry.entry_class, entry.findings) == ("unclassified", ("unknown-form",))


def test_a_bundled_entry_takes_its_nearest_unbundled_ancestors_class() -> None:
    """A bundled chain inherits from the first unbundled ancestor, and an unpinned one unpins it."""

    def edit(document: Document) -> None:
        """Remove the bundling package's digest and nest one bundled entry under another."""
        packages = document["packages"]
        del packages["node_modules/bundle-dependencies"]["integrity"]
        packages["node_modules/bundle-dependencies/node_modules/yargs/node_modules/deep"] = {
            "version": "1.0.0",
            "inBundle": True,
        }
        packages["node_modules/bundle-dependencies/node_modules/yargs"]["inBundle"] = True

    entries = _entries(_edited(V3, edit))
    deep = entries["node_modules/bundle-dependencies/node_modules/yargs/node_modules/deep"]
    assert deep.inherited_from == "node_modules/bundle-dependencies"
    assert (deep.entry_class, deep.form, deep.findings) == (
        "unpinned",
        "artifact",
        ("missing-digest",),
    )
    assert deep.digest_scope == "parent-artifact"


def test_a_bundled_entry_under_a_local_or_git_ancestor_inherits_that_class() -> None:
    """Inheritance keeps the ancestor's class and commit algorithm, not only artifact pins."""

    def edit(document: Document) -> None:
        """Bundle one entry under the git package and one under the link target."""
        packages = document["packages"]
        packages["node_modules/is-number/node_modules/a"] = {"version": "1.0.0", "inBundle": True}
        packages["local-lib/node_modules/b"] = {"version": "1.0.0", "inBundle": True}

    entries = _entries(_edited(V3, edit))
    git_child = entries["node_modules/is-number/node_modules/a"]
    assert (git_child.entry_class, git_child.commit_hash_algorithm) == ("commit-pinned", "sha1")
    local_child = entries["local-lib/node_modules/b"]
    assert (local_child.entry_class, local_child.inherited_from) == ("local", "local-lib")


def test_version_1_bundled_and_nested_entries_are_keyed_by_their_path() -> None:
    """A version 1 tree entry is keyed by its ``node_modules`` path and inherits when bundled."""

    def edit(document: Document) -> None:
        """Nest one unbundled registry package under ``debug``."""
        document["dependencies"]["debug"]["dependencies"] = {
            "nested": {
                "version": "1.0.0",
                "resolved": "https://registry.npmjs.org/nested/-/nested-1.0.0.tgz",
                "integrity": SHA1,
            }
        }

    entries = _entries(_edited(V1, edit))
    nested = entries["node_modules/debug/node_modules/nested"]
    assert (nested.entry_class, nested.findings) == ("unpinned", ("weak-digest",))
    yargs = entries["node_modules/bundle-dependencies/node_modules/yargs"]
    assert yargs.inherited_from == "node_modules/bundle-dependencies"


@pytest.mark.parametrize(
    ("edit", "reason"),
    [
        (lambda document: document.pop("lockfileVersion"), "missing-version"),
        (lambda document: document.update(lockfileVersion=4), "unsupported-version"),
        (lambda document: document.update(lockfileVersion=0), "unsupported-version"),
        (lambda document: document.update(lockfileVersion="3"), "unsupported-version"),
        (lambda document: document.update(lockfileVersion=True), "unsupported-version"),
        (lambda document: document.pop("packages"), "unparseable"),
        (lambda document: document.update(packages=[]), "unparseable"),
        (lambda document: document["packages"].update({"node_modules/x": "1.0.0"}), "unparseable"),
    ],
)
def test_a_version_3_file_that_cannot_be_classified_is_refused(
    edit: Callable[[Document], object], reason: str
) -> None:
    """Every file-level defect refuses the whole file with its named reason.

    Parameters
    ----------
    edit : Callable[[Document], object]
        The recorded edit of the clean version 3 fixture.
    reason : str
        The expected refusal reason.
    """

    def apply(document: Document) -> None:
        """Apply the edit."""
        edit(document)

    with pytest.raises(LockfileRefusal) as refused:
        classify_npm_lockfile(_edited(V3, apply), "", DEFAULT_NPM_REGISTRY)
    assert refused.value.reason == reason


def test_a_version_1_tree_that_is_not_objects_is_unparseable() -> None:
    """A version 1 tree level or entry that is not an object refuses the file."""
    cases: tuple[dict[str, object], ...] = ({"dependencies": []}, {"dependencies": {"x": []}})
    for broken in cases:

        def edit(document: Document, broken: dict[str, object] = broken) -> None:
            """Replace the tree."""
            document.update(broken)

        with pytest.raises(LockfileRefusal) as refused:
            classify_npm_lockfile(_edited(V1, edit), "", DEFAULT_NPM_REGISTRY)
        assert refused.value.reason == "unparseable"
    _, entries = classify_npm_lockfile('{"lockfileVersion": 1}', "", DEFAULT_NPM_REGISTRY)
    assert entries == ()


def test_a_duplicated_package_key_is_a_conflict() -> None:
    """Two entries under one key refuse the file rather than keeping the last."""
    text = fixture_text(V3)
    original = '    "node_modules/ms": {'
    assert text.count(original) == 1
    duplicated = text.replace(original, '    "node_modules/ms": {},\n' + original)
    with pytest.raises(LockfileRefusal) as refused:
        classify_npm_lockfile(duplicated, "", DEFAULT_NPM_REGISTRY)
    assert refused.value.reason == "conflicting-entries"


@pytest.mark.parametrize("field_name", ["integrity", "resolved"])
def test_a_version_2_legacy_tree_that_disagrees_with_packages_is_a_conflict(
    field_name: str,
) -> None:
    """Npm 6 reads the legacy tree, so a digest or URL it records differently is refused.

    Parameters
    ----------
    field_name : str
        The legacy field edited for ``debug``.
    """

    def edit(document: Document) -> None:
        """Change one legacy field."""
        document["dependencies"]["debug"][field_name] = (
            SHA512 if field_name == "integrity" else "https://evil.example/debug-4.3.4.tgz"
        )

    with pytest.raises(LockfileRefusal) as refused:
        classify_npm_lockfile(_edited(V2, edit), "", DEFAULT_NPM_REGISTRY)
    assert refused.value.reason == "conflicting-entries"


def test_a_version_2_legacy_entry_absent_from_packages_is_not_compared() -> None:
    """Legacy entries with no ``packages`` counterpart, or with other fields, are not conflicts."""

    def edit(document: Document) -> None:
        """Add a legacy-only entry and a legacy git version spelling."""
        document["dependencies"]["legacy-only"] = {"version": "1.0.0", "integrity": SHA1}
        document["packages"]["node_modules/odd"] = {
            "version": "1.0.0",
            "link": True,
            "resolved": "odd",
        }
        document["dependencies"]["odd"] = {"version": "file:odd"}

    entries = _entries(_edited(V2, edit))
    assert "node_modules/legacy-only" not in entries
    assert entries["node_modules/odd"].entry_class == "local"


@pytest.mark.parametrize("path", [V1, V2, V3])
def test_each_fixture_is_the_exact_output_its_generator_recorded(path: Path) -> None:
    """The decompressed fixture has the SHA-256 recorded when npm generated it.

    Parameters
    ----------
    path : Path
        The compressed fixture.
    """
    recorded = (path.parent / "GENERATED_BY.txt").read_text(encoding="utf-8").splitlines()
    digest = next(line.split()[1] for line in recorded if line.startswith("sha256 "))
    assert hashlib.sha256(fixture_text(path).encode("utf-8")).hexdigest() == digest
